use vstd::prelude::*;

verus! {
    fn all_characters_same(char_arr: &Vec<char>) -> (result: bool)
        requires
            char_arr.len() <= 1 || (char_arr.len() > 1 && char_arr[0] == char_arr[1..].iter().fold(char_arr[0], |acc, &c| acc == c)),
        ensures
            (char_arr.len() == 0 || char_arr.len() == 1) ==> result == true
        && (char_arr.len() > 1) ==> (result == (char_arr[1..].iter().all(|&c| c == char_arr[0])))
    {
        if char_arr.len() <= 1 {
            return true; // If the array is empty or has one character, return true.
        }

        let first_char = char_arr[0];
        let mut idx: usize = 1; // Start checking from the second character.

        while idx < char_arr.len()
            invariant
                idx <= char_arr.len(),
                result == (idx == char_arr.len() || char_arr[idx] == first_char),
            decreases char_arr.len() - idx,
        {
            if char_arr[idx] != first_char {
                return false; // If any character is different, return false.
            }
            idx += 1; // Move to the next character.
        }

        true // If we finish the loop without returning false, all characters are the same.
    }
}

